SELECT feedback_id, feedback_content, feedback_attachment, user_id, user_name, user_type, create_time, update_time FROM t_feedback
AND INSTR(feedback_content, #{query.searchWord})
AND DATE_FORMAT(create_time, '%Y-%m-%d') >= #{query.startDate}
AND DATE_FORMAT(create_time, '%Y-%m-%d') <= #{query.endDate}
ORDER BY create_time DESC
